'use strict';
const $ = id => document.getElementById(id);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state = {lang:new URLSearchParams(location.search).get('lang')==='en'?'en':'de',view:'welcome',profile:null,draft:null,schema:null,csrfToken:'',connected:false,coupon:false,invitation:false,filter:'recommended',request:'',response:false,intakeFields:{},intakeStep:0,adminFields:{},busy:false,localRequests:[],notice:'',adminNotice:''};
const tr = (de,en) => state.lang==='en'?en:de;
const address = (formal,informal) => state.profile?.informalAddressApproved===true?informal:formal;
const tx = (formal,informal,en) => tr(address(formal,informal),en);
const fields = () => state.profile?.fields||{};
const isAccounting = () => !state.profile?.segments?.length||state.profile.segments.includes('accounting');
const organization = () => fields().org_name||tr('Noch kein freigegebenes Profil','No approved profile yet');
const isReviewed = () => state.profile?.review?.status==='reviewed';
const routes = ['welcome','collaboration','requests','resources','support'];
const routeLabels = () => [tr('Willkommen','Welcome'),tr('Zusammenarbeit','Our work together'),tr('Anliegen & Worker','Requests & assistant'),tr('Impulse & Downloads','Ideas & resources'),tr('Gespräch & Unterstützung','Conversation & support')];
async function api(path,body){const options=body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Demo-Token':state.csrfToken},body:JSON.stringify(body)};const response=await fetch('/api'+path,options);const data=await response.json().catch(()=>({}));if(!response.ok){const error=new Error(data.error?.message||tr('Die lokale Aktion ist fehlgeschlagen.','The local action failed.'));error.code=data.error?.code;throw error;}return data;}
async function refresh(){const data=await api('/state');state.profile=data.profile||null;state.draft=data.draft||null;state.csrfToken=data.csrfToken||'';state.connected=true;if(state.draft)state.adminFields={...state.draft.fields};return data;}
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>{$('toast').hidden=true;},6500);}
function go(view){if(![...routes,'admin','onboarding'].includes(view))view='welcome';if(location.hash==='#'+view)render();else location.hash=view;}
function button(text,view,secondary=false){return `<button type="button" class="button${secondary?' secondary':''}" data-view="${view}">${esc(text)}<span class="arrow" aria-hidden="true">↗</span></button>`;}
function pill(text){return `<span class="status-pill">${esc(text)}</span>`;}
function head(kicker,title,intro,extra=''){return `<header class="view-head"><div class="head-row"><span class="eyebrow">${esc(kicker)}</span>${extra}</div><h1>${esc(title)}</h1><p class="intro">${esc(intro)}</p></header>`;}
function caption(){return `<div class="demo-caption">${tr('Fiktives Beispiel im lokalen Prototyp · kein tatsächlicher Auftrag an Robin.','Fictional example in this local prototype · no actual request has been sent to Robin.')}</div>`;}
function status(){return isReviewed()?tr('Im Prototyp administrativ geprüft','Reviewed in this prototype'):tr('Selbstauskunft · Prüfung offen','Self-reported · review pending');}
function chrome(){document.documentElement.lang=state.lang;document.title=tr('Memberpilot · robin.vision','Member pilot · robin.vision');$('prototype-label').textContent=tr('LOKALER PROTOTYP · Beispieldaten. Keine Anmeldung, Zahlung, echte KI oder Nachrichten.','LOCAL PROTOTYPE · Example data. No sign-in, payments, live AI or messages.');$('space-label').textContent=tr('Ein Raum für Entwicklung','A space for progress');$('admin-toggle').textContent=state.view==='admin'?tr('Zur Memberansicht','Member view'):tr('Admin-Demo','Admin demo');$('pilot-label').textContent=tr('Kostenfreier Memberpilot','Complimentary member pilot');$('pilot-dates').textContent=tr('15. Oktober 2026 bis 31. Januar 2027','15 October 2026 to 31 January 2027');$('pilot-note').textContent=tr('Endet automatisch. Kein Abonnement.','Ends automatically. No subscription.');$('footer-note').textContent=tr('Gemeinsam klarer sehen. Schritt für Schritt weiterkommen.','See things clearly together. Make progress, step by step.');$('main-nav').setAttribute('aria-label',tr('Memberbereiche','Member sections'));$('main-nav').innerHTML=routes.map((r,i)=>`<a class="nav-item" href="#${r}" ${state.view===r?'aria-current="page"':''}><span class="nav-number">0${i+1}</span><span>${esc(routeLabels()[i])}</span></a>`).join('');document.querySelectorAll('[data-language]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.language===state.lang)));$('close-dialog').setAttribute('aria-label',tr('Schließen','Close'));}
function followupDate(value){if(!value)return '';const date=new Date(/^\d{4}-\d{2}-\d{2}$/.test(value)?value+'T12:00:00Z':value);return Number.isNaN(date.valueOf())?value:new Intl.DateTimeFormat(state.lang==='de'?'de-DE':'en-GB',{day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Berlin'}).format(date);}
function followup(){const f=state.profile?.followup||{};const note=f.text||tx('Wir schauen gemeinsam, wo Ihre Idee gerade steht und welche Rückfrage sie weiterbringt.','Wir schauen gemeinsam, wo deine Idee gerade steht und welche Rückfrage sie weiterbringt.','We look at where your idea stands and which question will help move it forward.');return `<section class="section"><div class="followup"><div><span class="small-label">${tr('Robin bleibt am Thema · fiktives Beispiel','Robin stays involved · fictional example')}</span><h3>${tr('Was braucht der nächste Schritt ?','What does the next step need?')}</h3><p>${esc(note)}</p>${f.nextAt?`<p class="help" style="margin-top:12px">${tr('Lokale Wiedervorlage: ','Local follow-up date: ')}${esc(followupDate(f.nextAt))}</p>`:''}</div><button type="button" class="text-link" data-view="support">${tr('Gespräch vorbereiten','Prepare a conversation')} ↗</button></div>${caption()}</section>`;}

function welcome(){const vision=fields().vision;return `<div class="hero-layout"><div>${head(tr('Willkommen im Memberpilot','Welcome to the member pilot'),tr('Aus Ideen wird eine Richtung.','Give your ideas a direction.'),tx(`Hier bringen wir Ihre Vision, den Alltag ${isAccounting()?'Ihrer Kanzlei':'Ihres Unternehmens'} und die nächsten Schritte zusammen. Mit Raum zum Denken – und Robin an Ihrer Seite.`,`Hier bringen wir deine Vision, den Alltag ${isAccounting()?'deiner Kanzlei':'deines Unternehmens'} und die nächsten Schritte zusammen. Mit Raum zum Denken – und Robin an deiner Seite.`,'A place to connect your vision, everyday work and the next practical steps. Space to think, with Robin alongside you.'))}<div class="action-row">${button(tr('Zusammenarbeit ansehen','Explore our work together'),'collaboration')}<button type="button" class="text-link" id="show-voucher">${tr('Einladung ausprobieren','Try an invitation')}</button></div></div><aside class="hero-aside"><span class="small-label">${tr('Unser Ausgangspunkt','Our starting point')}</span><blockquote>${esc(vision||tx('Was soll für Sie und Ihr Team möglich werden ?','Was soll für dich und dein Team möglich werden ?','What would you like to make possible for your team?'))}</blockquote><span class="small">${esc(vision?status():tr('Die Antwort darf sich entwickeln.','The answer can take shape as we go.'))}</span></aside></div>
<div id="voucher-panel" class="coupon-form form-panel" hidden><span class="small-label">${tr('Persönliche Einladung','Personal invitation')}</span><h3 style="margin:8px 0 12px">${tr('Ein guter Anfang.','A good place to start.')}</h3><p class="small">${tr('Robin richtet das Profil vor der ersten Einladung ein. DEMO-2026 zeigt diesen Ablauf lokal, ohne Registrierung oder Vertrag.','Robin sets up the profile before the first invitation. DEMO-2026 demonstrates that process locally, without registration or a contract.')}</p><form id="voucher-form"><label class="field-label" for="voucher-code">${tr('Democode','Demo code')}</label><div class="inline-form"><input class="input" id="voucher-code" value="DEMO-2026" maxlength="30" autocomplete="off"><button type="submit" class="button">${tr('Einladung öffnen','Open invitation')} ↗</button></div></form><p class="help">${tr('Der geplante Pilot endet am 1. Februar 2027 um 00:00 Uhr (Europe/Berlin), ohne automatisches Abo.','The planned pilot ends on 1 February 2027 at 00:00 (Europe/Berlin), with no automatic subscription.')}</p></div>
<section class="section"><div class="section-top"><h2>${tr('Hier geht es weiter.','Make a start here.')}</h2><span>${tr('Ein gemeinsamer Weg','A shared path')}</span></div><div class="entry-list">${[[tr('Die eigene Richtung festhalten','Keep your direction in view'),tr('Vision, Engpässe und Prioritäten – aus dem von Robin vorbereiteten Profil.','Vision, challenges and priorities, from the profile prepared by Robin.'),'collaboration'],[tr('Eine konkrete Frage mitbringen','Bring a specific question'),tr('Aus einem Gedanken wird eine gut vorbereitete Anfrage an Robin.','Turn a thought into a clear, well-prepared request for Robin.'),'requests'],[tr('Passende Impulse entdecken','Find relevant ideas'),tr('Anregungen und Arbeitsblätter, die zum aktuellen Thema passen.','Ideas and worksheets that connect with what you are working on.'),'resources']].map((r,i)=>`<a class="entry" href="#${r[2]}"><span class="entry-number">0${i+1}</span><div><h3>${r[0]}</h3><p>${r[1]}</p></div><span class="entry-action" aria-hidden="true">↗</span></a>`).join('')}</div></section>${followup()}`;}
function contextItem(label,value,note){return `<div class="context-item"><span class="small-label">${esc(label)}</span><div class="context-value${value?'':' empty'}">${esc(value||tr('Noch offen','Still open'))}</div><p>${esc(note)}</p></div>`;}
function collaboration(){const f=fields();return `${head(tr('Zusammenarbeit','Our work together'),tx('Ihre Richtung. Unser gemeinsamer Stand.','Deine Richtung. Unser gemeinsamer Stand.','Your direction. Our shared understanding.'),tr('Ein überschaubarer Ort für das, was wichtig ist. Bestätigte Angaben, offene Fragen und Entscheidungen bleiben nachvollziehbar.','One clear place for what matters. Confirmed information, open questions and decisions stay easy to follow.'))}<div class="summary-strip"><div><span class="small-label">${tr('Organisation · Beispieldaten','Organization · example data')}</span><h3>${esc(organization())}</h3><p>${esc(status())}</p></div><a class="text-link" href="/downloads/pilot-questionnaire-${state.lang}.pdf" download>${tr('Profilbogen herunterladen','Download questionnaire')} ↓</a></div>${state.draft?`<div class="summary-strip"><div><span class="small-label">${tr('Neue Selbstauskunft','New self-reported information')}</span><p>${tr('Eine neue Fassung liegt zur Prüfung vor. Der bisherige Stand wird erst nach ausdrücklicher Adminfreigabe ersetzt.','A new version is awaiting review. It replaces the previous version only after explicit admin approval.')}</p></div>${pill(tr('Prüfung offen','Review pending'))}</div>`:''}<div class="context-grid">${contextItem(tr('Vision','Vision'),f.vision,tr('Wofür sich der nächste Schritt lohnen soll.','What will make the next step worthwhile.'))}${contextItem(tr('Erster Schwerpunkt','First priority'),f.priority,tr('Ein Thema, an dem wir konkret weiterarbeiten.','One topic to take forward together.'))}${contextItem(tr('Was derzeit bremst','What gets in the way'),f.pain,tr('Aus der Selbstauskunft, noch keine Diagnose.','Self-reported information, not a diagnosis.'))}${contextItem(tr('Woran wir Fortschritt erkennen','How we will recognize progress'),f.success,tr('Ziele, Schätzungen und gemessene Ergebnisse bleiben getrennt.','Targets, estimates and measured results remain separate.'))}</div><div class="context-meta"><span>${tr('Grundlage: Selbstauskunft','Source: self-reported information')}</span><span>${esc(state.profile?.source?.filename||tr('Noch kein Profilbogen hinterlegt','No questionnaire on file yet'))}</span><span>${tr('Pilotaufnahme per Fragebogen','Pilot baseline questionnaire')}</span></div>${state.profile?.review?.note?`<div class="summary-strip"><div><span class="small-label">${tr('Notiz zum gemeinsamen Stand · lokale Adminfreigabe','Note on our shared understanding · local admin approval')}</span><p>${esc(state.profile.review.note)}</p></div></div>`:''}<section class="section"><div class="section-top"><h2>${tr('Was schon da ist.','Build on what is already there.')}</h2></div><div class="two-column"><div class="panel"><span class="small-label">${tr('Werkzeuge & Systeme','Tools & systems')}</span><h3>${esc(f.tools||tr('Gemeinsam ergänzen','Let’s fill this in together'))}</h3><p>${tr('Bestehende Lösungen werden berücksichtigt. Eine spätere Umsetzung im Unternehmen bleibt eine eigene Leistung.','Existing tools are part of the picture. Implementation within the business remains a separate service.')}</p></div><div class="panel"><span class="small-label">${tr('Zusammenarbeit','Collaboration')}</span><h3>${esc(choiceText('collaboration',f.collaboration)||tr('Was zum Alltag passt','What fits your working day'))}</h3><p>${esc(f.information_flow||tr('Wie Robin sich unkompliziert auf dem Stand halten kann, klären wir gemeinsam.','Together, we will find a simple way for Robin to stay up to date.'))}</p></div></div></section>${followup()}<details class="disclosure"><summary>${tr('Wie aus Angaben ein gemeinsamer Stand wird','How information becomes a shared understanding')}</summary><p>${tr('Im Pilot legt Robin das Profil vor der ersten Einladung an. Ein ausgefüllter Profilbogen wird eingelesen, geprüft und ausdrücklich freigegeben. Dieser Prototyp bildet den Ablauf nach; die lokale Adminfreigabe weist keine tatsächliche Prüfung durch Robin nach.','In the pilot, Robin creates the profile before the first invitation. A completed questionnaire is imported, reviewed and explicitly approved. This prototype demonstrates the process; local admin approval is not evidence of an actual review by Robin.')}</p></details>`;}
function requestsView(){return `${head(tr('Anliegen & Worker','Requests & assistant'),tr('Mit einer guten Frage beginnt Bewegung.','A good question sets things in motion.'),tx('Der Worker hilft, Ihr Anliegen vorzubereiten. Robin übernimmt die persönliche Einordnung. Hier lässt sich der Ablauf mit einem festen Beispiel erkunden.','Der Worker hilft, dein Anliegen vorzubereiten. Robin übernimmt die persönliche Einordnung. Hier lässt sich der Ablauf mit einem festen Beispiel erkunden.','The assistant helps you prepare your request; Robin adds his personal judgement. Explore that process with a fixed demonstration.'))}<div class="prompt-choices">${[tr('Einen Ablauf verbessern','Improve a process'),tr('Eine Idee weiterdenken','Develop an idea'),tr('Das Team mitnehmen','Bring the team along')].map((p,i)=>`<button type="button" class="prompt-choice" data-prompt="${i}">${p} ↗</button>`).join('')}</div><form id="request-form" class="form-panel"><label class="field-label" for="request-text">${tx('Was beschäftigt Sie gerade ?','Was beschäftigt dich gerade ?','What is on your mind?')}</label><textarea id="request-text" maxlength="2400" placeholder="${esc(tr('Zum Beispiel: Neue Mitarbeitende sollen schneller sicher im Alltag ankommen.','For example: Help new team members find their feet more quickly.'))}">${esc(state.request)}</textarea><p class="help">${tr('Bitte nur fiktive Beispiele verwenden. Keine Mandanten-, Beschäftigten- oder Zugangsdaten.','Please use fictional examples only. No client or employee information or credentials.')}</p><div class="action-row"><button class="button" type="submit">${tr('Vorbereitung ausprobieren','Try preparing a request')} ↗</button><span class="small">${tr('Fester Demoablauf · kein KI-Aufruf','Fixed demonstration · no AI request')}</span></div></form>${state.response?`<section class="worker-response"><span class="small-label">${tr('Vorbereitungsentwurf · feste Demo, nicht von Robin geprüft','Preparation draft · fixed demo, not reviewed by Robin')}</span><h3>${tr('Drei Fragen bringen uns weiter.','Three questions to take this forward.')}</h3><ol><li>${tr('Welches konkrete Ergebnis soll sich für das Team verbessern ?','What specific outcome should improve for the team?')}</li><li>${tr('Wie läuft die Aufgabe heute ab, und wo stockt sie ?','How does the task work today, and where does it get stuck?')}</li><li>${tr('Was funktioniert bereits gut und soll erhalten bleiben ?','What already works well and should be preserved?')}</li></ol><p class="request-summary">${esc(state.request)}</p><button type="button" class="text-link" id="save-request">${tr('Als Demoanliegen vormerken','Save as a demo request')} ↗</button><p class="help">${tr('Bleibt nur in dieser Browseransicht. Es wird nichts an Robin gesendet.','Stays only in this browser view. Nothing is sent to Robin.')}</p></section>`:''}<div class="budget-line"><span>${tr('KI-Budget: im Prototyp nicht aktiv','AI allowance: not active in this prototype')}</span><span>${tr('Keine unbegrenzte Nutzung zugesagt','No unlimited usage is promised')}</span></div><section class="section"><div class="section-top"><h2>${tr('So geht es danach weiter.','What happens next.')}</h2></div><ol class="step-list">${[[tr('Anliegen verstehen','Understand the request'),tr('Ausgangslage, gewünschtes Ergebnis und offene Fragen zusammenführen.','Bring together the starting point, desired outcome and open questions.')],[tr('Persönlich einordnen','Add personal judgement'),tr('Robin prüft eine konkrete Fassung und ergänzt seine Einschätzung. Entwurf und Prüfung bleiben erkennbar.','Robin reviews a specific version and adds his judgement. Draft and review remain clearly distinct.')],[tr('Den nächsten Schritt festhalten','Agree the next step'),tr('Eine Entscheidung, ein Gespräch oder ein gesondert vereinbarter Umsetzungsauftrag.','A decision, a conversation or a separately agreed implementation project.')]].map(([a,b])=>`<li><div><h3>${a}</h3><p>${b}</p></div></li>`).join('')}</ol></section>${state.localRequests.length?`<section class="section"><span class="small-label">${tr('Nur lokal vorgemerkt','Saved locally only')}</span>${state.localRequests.map(r=>`<div class="event-line">${esc(r)}</div>`).join('')}</section>`:''}`;}
const resources=[{id:'questionnaire',type:['Ausfüllbarer Profilbogen · PDF','Fillable questionnaire · PDF'],title:['Ihre Kanzlei. Ihr Unternehmen. Ihre Vision.','Your firm. Your business. Your vision.'],desc:['Die Grundlage für das persönliche Profil. Robin prüft die Angaben vor der Einladung.','The starting point for a personal profile. Robin reviews the answers before the invitation.'],tag:'all',icon:'01'},{id:'onboarding',type:['Arbeitsimpuls · Beispiel','Working note · example'],title:['Ein guter erster Monat entsteht vor dem ersten Arbeitstag.','A good first month starts before the first working day.'],desc:['Einarbeitung als gemeinsamer Ablauf: Orientierung, Verantwortung und Rückfragen.','Onboarding as a shared process: clarity, responsibility and questions.'],tag:'accounting',icon:'02'},{id:'handoff',type:['Arbeitsblatt · Beispiel','Worksheet · example'],title:['Die Übergabe, an der alles hängen bleibt.','The handover that holds everything up.'],desc:['Einen Ablauf sichtbar machen, bevor ein neues Werkzeug dazukommt.','Make a process visible before introducing another tool.'],tag:'all',icon:'03'},{id:'vision',type:['Entscheidungshilfe · Beispiel','Decision aid · example'],title:['Welche digitale Idee verdient den nächsten Schritt ?','Which digital idea deserves the next step?'],desc:['Nutzen, Machbarkeit und eine kleine erste Erprobung zusammen betrachten.','Consider value, feasibility and a small first trial together.'],tag:'business',icon:'04'}];
resources.push({id:'einvoice',type:['Arbeitsimpuls · Unternehmen','Working note · businesses'],title:['Aus Rechnungsdaten wird ein Ablauf.','Turn invoice data into a workflow.'],desc:['Lesen, prüfen, weiterarbeiten: der Einstieg in weniger Übertragungsarbeit. Das E-Rechnungstool ist geplant.','Read, check and act: a starting point for less manual data entry. The e-invoicing tool is planned.'],tag:'business',icon:'05'});
function resourcesView(){const segment=isAccounting()?'accounting':'business';const shown=resources.filter(r=>state.filter==='all'||r.tag==='all'||r.tag===(state.filter==='recommended'?segment:state.filter));return `${head(tr('Impulse & Downloads','Ideas & resources'),tr('Gute Gedanken, passend zum Moment.','Useful ideas, at the right moment.'),tr('Vertiefungen, Fragen und Arbeitsblätter für die Themen, an denen wir gemeinsam arbeiten. Die Auswahl hier ist ein Beispiel für den Memberpilot.','Notes, questions and worksheets for the topics we are working on together. This selection illustrates the member pilot.'))}<div class="filter-row">${[['recommended',tr('Passend zum Profil','For your profile')],['accounting',tr('Kanzlei','Accounting firms')],['business',tr('Unternehmen','Businesses')],['all',tr('Alle Impulse','All resources')]].map(([id,label])=>`<button type="button" class="filter" data-filter="${id}" aria-pressed="${state.filter===id}">${label}</button>`).join('')}</div>${shown.map(r=>`<article class="resource-row"><div class="resource-art" aria-hidden="true">${r.icon}</div><div><span class="resource-kind">${esc(r.type[state.lang==='de'?0:1])}</span><h3>${esc(r.title[state.lang==='de'?0:1])}</h3><p>${esc(r.desc[state.lang==='de'?0:1])}</p></div><button type="button" data-resource="${r.id}" aria-label="${esc(tr('Öffnen: ','Open: ')+r.title[state.lang==='de'?0:1])}">↗</button></article>`).join('')}<section class="section"><div class="followup"><div><span class="small-label">${tr('Vom Lesen zum eigenen Anliegen','From reading to your own question')}</span><h3>${tr('Was davon ist gerade relevant ?','What matters to you right now?')}</h3><p>${tr('Ein Impuls wird wertvoll, wenn wir ihn mit dem tatsächlichen Alltag verbinden.','An idea becomes useful when we connect it with everyday work.')}</p></div><button type="button" class="text-link" data-view="requests">${tr('Anliegen vorbereiten','Prepare a request')} ↗</button></div></section>`;}
const demoSlots=['2026-10-16 10:00','2026-10-19 14:00','2026-10-21 09:00','2026-10-23 11:00','2026-10-26 15:00'];
function appointmentSlots(){return `<section class="section"><div class="section-top"><h2>${tr('Mehr Raum für ein Gespräch.','More room for a conversation.')}</h2><span>${tr('Fünf fiktive Memberfenster','Five fictional member slots')}</span></div><p class="intro">${tr('Ein Beratungsgespräch gehört zum Pilotzugang. Hier wird die zusätzliche Terminauswahl für Members gezeigt. Die Daten sind Beispiele, keine freien Zeiten aus Robins Kalender.','The pilot includes one consultation. This shows the additional appointment choice for members. These are examples, not available times from Robin’s calendar.')}</p>${demoSlots.map((slot,i)=>`<div class="appointment"><div><h3>${esc(followupDate(slot.slice(0,10)))} · ${slot.slice(11)}</h3><p>${tr('Europe/Berlin · nur lokale Vorschau','Europe/Berlin · local preview only')}</p></div><button type="button" class="text-link" data-slot="${i}">${tr('Terminwunsch vormerken','Prepare appointment request')} ↗</button></div>`).join('')}</section>`;}
function supportView(){return `${head(tr('Gespräch & Unterstützung','Conversation & support'),tr('Ein direkter Draht. Und ein gemeinsamer Blick.','A direct connection. A shared perspective.'),tx('Manches lässt sich schriftlich klären. Anderes braucht ein Gespräch. Hier bereiten Sie den passenden nächsten Schritt vor.','Manches lässt sich schriftlich klären. Anderes braucht ein Gespräch. Hier bereitest du den passenden nächsten Schritt vor.','Some things are easier in writing; others need a conversation. Prepare the right next step here.'))}<div class="followup"><div><span class="small-label">${tr('Robin fragt nach · fiktives Beispiel','Robin follows up · fictional example')}</span><h3>${tr('Hat sich beim ersten Thema etwas verändert ?','Has anything changed with your first priority?')}</h3><p>${tr('Was ist seit dem letzten Stand gelungen, was ist offen und wo wäre Unterstützung hilfreich ?','What has moved forward, what is still open, and where would support help?')}</p></div><button type="button" class="text-link" id="followup-reply">${tr('Antwort vorbereiten','Prepare a reply')} ↗</button></div>${caption()}${appointmentSlots()}<section class="section"><div class="section-top"><h2>${tr('Was jetzt gut passen könnte.','What might help right now.')}</h2><span>${tr('Keine echten Termine','No live bookings')}</span></div>${[[tr('Ein Thema gemeinsam sortieren','Think a topic through together'),tr('Ziele klären, Alternativen abwägen und einen nächsten Schritt finden.','Clarify goals, weigh alternatives and find a next step.')],[tr('Ein Ergebnis besprechen','Discuss an outcome'),tr('Einen Entwurf einordnen oder eine Entscheidung vorbereiten.','Review a draft or prepare a decision.')],[tr('Umsetzung oder Unterstützung anfragen','Ask about implementation or support'),tr('Ein konkretes Vorhaben und den gesonderten Leistungsumfang klären.','Discuss a concrete project and its separately agreed scope.')]].map(([title,desc],i)=>`<div class="appointment"><div><h3>${title}</h3><p>${desc}</p></div><button type="button" class="text-link" data-meeting="${i}">${tr('Demo vorbereiten','Prepare a demo')} ↗</button></div>`).join('')}</section><section class="section two-column"><div class="panel"><span class="small-label">${tr('Zusammenarbeit im Pilot','Working together in the pilot')}</span><h3>${tr('Raum für Rückfragen.','Room for questions.')}</h3><p>${tr('Ein leicht zugänglicher Weg zu Robin gehört zum geplanten Angebot. Reaktionszeiten und Umfang werden vor dem kostenpflichtigen Start konkret vereinbart.','An easy way to reach Robin is part of the planned offer. Response times and scope will be agreed before the paid service begins.')}</p></div><div class="panel"><span class="small-label">${tr('Wenn etwas umgesetzt werden soll','When it is time to implement')}</span><h3>${tr('Der passende Auftrag.','The right agreement.')}</h3><p>${tr('Projekte, Beratung und operative Unterstützung werden gesondert vereinbart. Dieser Prototyp schließt keine Verträge und reserviert keine Termine.','Projects, consulting and operational support are agreed separately. This prototype creates no contracts or bookings.')}</p></div></section>`;}
function choiceText(name,value){if(!value)return '';const field=state.schema?.fields.find(f=>f.name===name);if(!field?.options)return value;let i=field.options.de.indexOf(value);if(i<0)i=field.options.en.indexOf(value);return i>=0?field.options[state.lang][i]:value;}
function renderField(field,value,prefix){const id=`${prefix}-${field.name}`;const common=`id="${id}" name="${field.name}" data-field="${field.name}" ${field.maxLength?`maxlength="${field.maxLength}"`:''}`;const label=field.label[state.lang];if(field.type==='checkbox')return `<label class="check-label" for="${id}"><input type="checkbox" ${common} ${value===true?'checked':''}><span>${esc(label)}</span></label>`;let control;if(field.type==='multiline')control=`<textarea ${common}>${esc(value||'')}</textarea>`;else if(field.type==='choice'){const options=field.options.de;control=`<select ${common}>${options.map((option,i)=>`<option value="${i===0?'':esc(option)}" ${value===option||(!value&&i===0)?'selected':''}>${esc(field.options[state.lang][i])}</option>`).join('')}${value&&!options.includes(value)?`<option value="${esc(value)}" selected>${esc(value)}</option>`:''}</select>`;}else control=`<input class="input" type="text" ${common} value="${esc(value||'')}" autocomplete="off">`;return `<div class="field"><label class="field-label" for="${id}">${esc(label)}</label>${control}${field.hint?`<p class="help">${esc(field.hint[state.lang])}</p>`:''}</div>`;}
const starterFields=['org_name','vision','pain','priority'];
function onboarding(){const intro=tr('Zukünftige Ausbaustufe, nicht die Aufnahme in den aktuellen Pilot: Später können neue Mitglieder ihre Angaben selbst online vorbereiten. Im Pilot legt ausschließlich Robin die Profile vor der Einladung an.','Future phase, not admission to the current pilot: later, new members can prepare their own information online. In the pilot, only Robin creates profiles, before sending an invitation.');if(!state.schema)return `${head(tr('Zukunftsvorschau · Onlineaufnahme','Future preview · online questionnaire'),tr('Vier Antworten genügen für den Anfang.','Four answers are enough to start.'),intro)}<p>${tr('Bitte den Prototyp über den lokalen Server öffnen, um die Fragen zu laden.','Please open the prototype through the local server to load the questions.')}</p>`;const more=state.intakeStep>0;const selected=state.schema.fields.filter(f=>more?!starterFields.includes(f.name):starterFields.includes(f.name));return `${head(tr('Zukunftsvorschau · keine Selbstregistrierung','Future preview · no self-registration'),more?tr('Mehr Kontext, wenn es gerade passt.','A little more context, when it suits you.'):tr('Vier Antworten. Ein erster gemeinsamer Stand.','Four answers. A shared starting point.'),intro)}<div class="summary-strip"><div><span class="small-label">${tr('Nur die spätere Aufnahme ausprobieren','Try the future questionnaire only')}</span><p>${tr('Stichpunkte genügen. Weitere Angaben sind optional; ein Zwischenstand lässt sich jederzeit speichern. Nur fiktive Daten verwenden.','A few words are enough. Further details are optional; save your progress at any time. Use fictional information only.')}</p></div><a class="text-link" href="/downloads/pilot-questionnaire-${state.lang}.pdf" download>${tr('PDF herunterladen','Download PDF')} ↓</a></div><form id="intake-form"><div class="form-panel">${selected.map(f=>renderField(f,state.intakeFields[f.name],'intake')).join('')}</div><p class="form-status" id="intake-status" role="status">${esc(state.notice)}</p><div class="action-row"><button type="button" class="button" id="submit-intake" ${state.busy?'disabled':''}>${tr('Zur Demo-Prüfung vormerken','Submit for demo review')} ↗</button><button type="button" class="text-link" id="save-intake" ${state.busy?'disabled':''}>${tr('Zwischenstand speichern','Save progress')}</button><button type="button" class="text-link" id="toggle-intake">${more?tr('Zu den vier ersten Fragen','Back to the first four questions'):tr('Weitere Angaben ergänzen','Add more details')}</button></div><p class="help">${tr('Speicherung nur im Arbeitsspeicher des lokalen Servers. Keine Nachricht wird versendet. Erst eine ausdrückliche Adminfreigabe verändert das Memberprofil.','Saved only in the local server’s memory. No message is sent. Only explicit admin approval updates the member profile.')}</p></form>`;}
function adminView(){const d=state.draft;return `<div class="admin-intro">${head(tr('Admin-Demo · nur lokal','Admin demo · local only'),tr('Erst das Profil. Dann die Einladung.','First the profile. Then the invitation.'),tr('Robin legt die Memberprofile zunächst selbst an: Profilbogen einlesen, Angaben prüfen und eine Fassung ausdrücklich freigeben. Erst danach wird eine persönliche Einladung vorbereitet.','Robin initially creates member profiles himself: import a questionnaire, review the information and explicitly approve a version. Only then is a personal invitation prepared.'))}</div><div class="admin-layout"><div><form id="upload-form" class="upload-zone"><span class="upload-icon" aria-hidden="true">↑</span><h3>${tr('Ausgefüllten Profilbogen einlesen','Import a completed questionnaire')}</h3><p>${tr('Ein ausfüllbares PDF der Vorlage, höchstens 2 MB. Felder werden lokal ausgelesen; keine KI-Auswertung und kein Upload zu einem externen Dienst.','Use a fillable PDF based on the template, up to 2 MB. Fields are read locally; no AI analysis or upload to an external service.')}</p><label class="field-label" for="pdf-file">${tr('PDF auswählen','Choose a PDF')}</label><input id="pdf-file" type="file" accept="application/pdf,.pdf"><button type="submit" class="button" ${state.busy?'disabled':''}>${tr('PDF lokal einlesen','Read PDF locally')} ↗</button><p class="form-status" role="status" id="upload-status">${esc(state.adminNotice)}</p><a class="pdf-link" href="/downloads/pilot-questionnaire-${state.lang}.pdf" download>${tr('Leere Vorlage herunterladen','Download a blank questionnaire')} ↓</a></form><section class="admin-controls"><span class="small-label">${tr('Bisheriger Memberstand','Current member profile')}</span><h3 style="margin:10px 0">${esc(organization())}</h3><p class="small">${esc(status())}</p><div class="tag-list"><span class="tag">${state.profile?.informalAddressApproved?tr('Du von Admin freigegeben','Informal German approved by admin'):tr('Sie · Standard','Formal German · default')}</span><span class="tag">${isAccounting()?tr('Kanzlei','Accounting firm'):tr('Unternehmen','Business')}</span></div><p class="help">${tr('Anrede und Zielgruppe sind Adminentscheidungen. Selbstauskunft und Gutschein ändern diese Rechte nicht.','Address style and audience are admin decisions. Self-reported answers and invitation codes do not change these permissions.')}</p></section><section class="admin-controls"><span class="small-label">${tr('Nach der Profilfreigabe','After profile approval')}</span><h3 style="margin:10px 0">${tr('Persönlich einladen.','Make it personal.')}</h3><p class="small">${tr('Nur ein Einladungsentwurf im Prototyp. Es werden weder Nachricht noch Gutschein versendet.','An invitation draft in the prototype only. No message or voucher is sent.')}</p><button type="button" class="button secondary" id="prepare-invitation" ${!isReviewed()?'disabled':''}>${tr('Demo-Einladung vorbereiten','Prepare a demo invitation')} ↗</button>${!isReviewed()?`<p class="help">${tr('Zuerst einen Profilbogen einlesen und ausdrücklich freigeben.','First import and explicitly approve a questionnaire.')}</p>`:''}${state.invitation?`<div class="worker-response"><span class="small-label">${tr('Einladungsentwurf · nicht versendet','Invitation draft · not sent')}</span><h4 style="margin:12px 0">${esc(organization())}</h4><p class="small">${tx('Ihr vorbereiteter Memberbereich wartet auf Sie. Mit dem Democode lässt sich die persönliche Ansicht erkunden.','Dein vorbereiteter Memberbereich wartet auf dich. Mit dem Democode lässt sich die persönliche Ansicht erkunden.','Your prepared member area is ready to explore. Use the demo code to open the personal view.')}</p><p><code>DEMO-2026</code></p><button type="button" class="text-link" id="preview-invitation">${tr('Einladung als Member ansehen','Preview invitation as a member')} ↗</button><p class="help">${tr('Befristet bis 01.02.2027, 00:00 Europe/Berlin. Kein Auto-Abo.','Valid until 1 February 2027, 00:00 Europe/Berlin. No automatic subscription.')}</p></div>`:''}</section><details class="disclosure"><summary>${tr('Spätere Ausbaustufe: Onlineaufnahme','Future phase: online questionnaire')}</summary><p>${tr('Neue Mitglieder könnten ihre Angaben später selbst vorbereiten. Diese Vorschau ist weder Registrierung noch Aufnahmebedingung für den aktuellen Pilot.','New members could later prepare their own information. This preview is neither registration nor a condition for joining the current pilot.')}</p><button type="button" class="text-link" data-view="onboarding">${tr('Zukunftsvorschau öffnen','Open future preview')} ↗</button></details></div>${d?`<form id="review-form" class="preview-form"><div class="head-row"><span class="small-label">${tr('Editierbare Vorschau','Editable preview')}</span>${pill(tr('Noch nicht freigegeben','Not approved yet'))}</div><h3 style="margin:13px 0">${esc(d.source?.filename||tr('Online-Selbstauskunft','Online questionnaire'))}</h3><p class="help" style="margin-bottom:20px">${tr('Nur tatsächlich gelesene Angaben. Leere Felder bleiben leer; jede Angabe lässt sich vor der Freigabe korrigieren.','Only information actually read. Empty fields stay empty; every answer can be corrected before approval.')}</p>${d.missing?.length?`<p class="upload-note">${tr('Noch offen: ','Still open: ')}${d.missing.map(k=>esc(state.schema?.fields.find(f=>f.name===k)?.label[state.lang]||k)).join(' · ')}</p>`:''}${d.warnings?.length?`<p class="upload-note">${esc(d.warnings.map(w=>typeof w==='string'?w:JSON.stringify(w)).join('\n'))}</p>`:''}<details class="disclosure" open><summary>${tr('Kernaussagen prüfen','Review the starting points')}</summary>${(state.schema?.fields||[]).filter(f=>starterFields.includes(f.name)).map(f=>renderField(f,state.adminFields[f.name],'review')).join('')}</details><details class="disclosure"><summary>${tr('Alle weiteren Angaben bearbeiten','Edit all remaining details')}</summary>${(state.schema?.fields||[]).filter(f=>!starterFields.includes(f.name)).map(f=>renderField(f,state.adminFields[f.name],'review')).join('')}</details><div class="admin-controls"><span class="small-label">${tr('Freigabe im lokalen Prototyp','Approval in the local prototype')}</span><label class="check-label"><input type="checkbox" id="informal-approved" ${state.profile?.informalAddressApproved?'checked':''}><span>${tr('Informelle Anrede „Du“ für dieses Profil freigeben','Approve informal German address for this profile')}</span></label><label class="field-label" for="segment">${tr('Zielgruppe für Impulse','Audience for suggested resources')}</label><select id="segment"><option value="accounting" ${isAccounting()?'selected':''}>${tr('Kanzlei','Accounting firm')}</option><option value="business" ${!isAccounting()?'selected':''}>${tr('Unternehmen / KMU','Business / SME')}</option></select><div class="field" style="margin-top:15px"><label class="field-label" for="review-note">${tr('Prüfnotiz / offene Punkte','Review note / open points')}</label><textarea id="review-note" maxlength="1200" placeholder="${esc(tr('Was wurde geprüft, was bleibt offen? Nur fiktive Angaben.','What was reviewed, what remains open? Fictional information only.'))}"></textarea></div><div class="field"><label class="field-label" for="followup-date">${tr('Wiedervorlage im Demoablauf (optional)','Demo follow-up date (optional)')}</label><input type="date" class="input" id="followup-date"></div><div class="field"><label class="field-label" for="followup-note">${tr('Nächste Rückfrage (fiktiv, optional)','Next follow-up question (fictional, optional)')}</label><textarea id="followup-note" maxlength="600"></textarea></div><label class="check-label"><input type="checkbox" id="review-confirm"><span>${tr('Ich habe diese Fassung im Prototyp geprüft und möchte sie ausdrücklich als lokalen Memberstand übernehmen. Das ist kein Nachweis einer echten Prüfung durch Robin.','I have reviewed this version in the prototype and explicitly want to apply it to the local member profile. This is not proof of a real review by Robin.')}</span></label><button type="submit" class="button" id="publish-profile" disabled>${tr('Geprüfte Fassung lokal freigeben','Approve this version locally')} ↗</button><p class="form-status" id="publish-status" role="status"></p></div></form>`:`<div class="empty-state"><span class="small-label">${tr('Bereit für den ersten Entwurf','Ready for a first draft')}</span><h3 style="margin-top:15px">${tr('Erst lesen. Dann entscheiden.','Read first. Then decide.')}</h3><p>${tr('Ein eingelesenes PDF erscheint hier. Vor der ausdrücklichen Freigabe wird nichts in das Memberprofil übernommen.','An imported PDF will appear here. Nothing is applied to the member profile before explicit approval.')}</p><ol class="step-list"><li><div><h4>${tr('Profilbogen erhalten','Receive the questionnaire')}</h4><p>${tr('Der ausgefüllte Bogen kommt vor der ersten Einladung zu Robin.','Robin receives the completed questionnaire before the first invitation.')}</p></div></li><li><div><h4>${tr('Angaben prüfen','Review the information')}</h4><p>${tr('Offene Punkte sichtbar lassen und den Stand freigeben.','Keep open points visible and approve the version.')}</p></div></li><li><div><h4>${tr('Persönlich einladen','Invite personally')}</h4><p>${tr('Der Member startet mit dem bereits vorbereiteten Profil.','The member begins with a profile already prepared.')}</p></div></li></ol></div>`}</div>`;}
function render(){state.view=location.hash.slice(1)||'welcome';if(![...routes,'admin','onboarding'].includes(state.view))state.view='welcome';chrome();const views={welcome,collaboration,requests:requestsView,resources:resourcesView,support:supportView,onboarding,admin:adminView};$('main').innerHTML=views[state.view]();bindView();}
function capture(form,target){if(!form)return;form.querySelectorAll('[data-field]').forEach(input=>{target[input.dataset.field]=input.type==='checkbox'?input.checked:input.value;});}
async function saveIntake(mode){if(state.busy)return;capture($('intake-form'),state.intakeFields);state.busy=true;const el=$(mode==='save'?'save-intake':'submit-intake');if(el)el.disabled=true;try{const data=await api('/intake',{fields:{...state.intakeFields},mode,language:state.lang});state.draft=data.draft;state.adminFields={...data.draft.fields};state.intakeFields={...data.draft.fields};state.notice=mode==='save'?tr('Zwischenstand lokal gespeichert. Das Memberprofil bleibt unverändert.','Progress saved locally. The member profile is unchanged.'):tr('Selbstauskunft zur Demo-Prüfung vorgemerkt. Noch keine Robin-Freigabe und keine Nachricht versendet.','Questionnaire submitted for demo review. Not approved by Robin, and no message has been sent.');}catch(error){state.notice=error.message;}state.busy=false;render();}
function bindView(){document.querySelectorAll('[data-slot]').forEach(b=>b.addEventListener('click',()=>{const slot=demoSlots[Number(b.dataset.slot)];state.request=tr('Fiktiver Terminwunsch für ','Fictional appointment request for ')+slot+' (Europe/Berlin)';state.response=false;go('requests');toast(tr('Terminwunsch nur lokal vorbereitet. Keine Buchung oder Nachricht.','Appointment request prepared locally. No booking or message.'));}));document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.view)));$('show-voucher')?.addEventListener('click',()=>{$('voucher-panel').hidden=!$('voucher-panel').hidden;if(!$('voucher-panel').hidden)$('voucher-code').focus();});$('voucher-form')?.addEventListener('submit',e=>{e.preventDefault();if($('voucher-code').value.trim().toUpperCase()!=='DEMO-2026'){toast(tr('Für diesen Prototyp gilt nur DEMO-2026.','This prototype accepts DEMO-2026 only.'));return;}if(!isReviewed()){toast(tr('Zuerst das Profil in der Admin-Demo prüfen und freigeben.','First review and approve the profile in the admin demo.'));go('admin');return;}state.coupon=true;toast(tr('Demoeinladung geöffnet. Der persönliche Stand ist vorbereitet.','Demo invitation opened. Your personal profile is ready.'));go('collaboration');});document.querySelectorAll('[data-prompt]').forEach(b=>b.addEventListener('click',()=>{const prompts=[tr('Ich möchte die Einarbeitung neuer Mitarbeitender klarer gestalten. Wo beginnen wir?','I want to make onboarding clearer for new team members. Where should we start?'),tr('Ich habe eine Idee für ein digitales Kundenportal. Wie prüfen wir, ob sie im Alltag hilft?','I have an idea for a digital customer portal. How can we check if it will help in practice?'),tr('Wir möchten einen Arbeitsablauf verändern. Wie beziehen wir das Team gut ein?','We want to change a workflow. How can we involve the team?')];state.request=prompts[+b.dataset.prompt];$('request-text').value=state.request;$('request-text').focus();}));$('request-text')?.addEventListener('input',e=>{state.request=e.target.value;});$('request-form')?.addEventListener('submit',e=>{e.preventDefault();state.request=$('request-text').value.trim();if(!state.request){toast(tr('Bitte ein fiktives Anliegen eingeben.','Please enter a fictional request.'));return;}state.response=true;render();document.querySelector('.worker-response')?.scrollIntoView({behavior:'smooth',block:'nearest'});});$('save-request')?.addEventListener('click',()=>{state.localRequests.push(state.request);toast(tr('Nur in dieser Ansicht vorgemerkt. Nichts wurde an Robin gesendet.','Saved in this view only. Nothing was sent to Robin.'));render();});document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{state.filter=b.dataset.filter;render();}));document.querySelectorAll('[data-resource]').forEach(b=>b.addEventListener('click',()=>openResource(b.dataset.resource)));document.querySelectorAll('[data-meeting]').forEach(b=>b.addEventListener('click',()=>{state.request=[tr('Ich möchte mein erstes Thema gemeinsam sortieren.','I would like to think through my first priority together.'),tr('Ich möchte einen Entwurf oder ein Ergebnis besprechen.','I would like to discuss a draft or an outcome.'),tr('Ich möchte den Umfang einer gesonderten Umsetzung klären.','I would like to discuss the scope of a separate implementation project.')][+b.dataset.meeting];state.response=false;go('requests');toast(tr('Gesprächsanlass vorbereitet. Kein Termin wurde gebucht.','Conversation topic prepared. No appointment was booked.'));}));$('followup-reply')?.addEventListener('click',()=>{state.request=tr('Seit unserem letzten Stand hat sich Folgendes verändert: ','Since our last update, the following has changed: ');state.response=false;go('requests');});$('intake-form')?.addEventListener('input',()=>capture($('intake-form'),state.intakeFields));$('save-intake')?.addEventListener('click',()=>saveIntake('save'));$('submit-intake')?.addEventListener('click',()=>saveIntake('submit'));$('toggle-intake')?.addEventListener('click',()=>{capture($('intake-form'),state.intakeFields);state.intakeStep=state.intakeStep?0:1;render();$('main').focus();window.scrollTo({top:0,behavior:'smooth'});});$('upload-form')?.addEventListener('submit',uploadPdf);$('review-form')?.addEventListener('input',()=>{capture($('review-form'),state.adminFields);if($('review-confirm'))$('publish-profile').disabled=!$('review-confirm').checked||state.busy;});$('review-form')?.addEventListener('submit',publishProfile);$('prepare-invitation')?.addEventListener('click',()=>{if(!isReviewed())return;state.invitation=true;render();toast(tr('Einladungsentwurf vorbereitet. Nicht versendet.','Invitation draft prepared. Not sent.'));});$('preview-invitation')?.addEventListener('click',()=>{go('welcome');setTimeout(()=>{if($('voucher-panel')){$('voucher-panel').hidden=false;$('voucher-code').focus();}},80);});}
function openResource(id){const item=resources.find(r=>r.id===id);if(!item)return;const content={einvoice:`<p>${tr('Eine Rechnung liefert mehr als ein Belegbild. Der erste Schritt ist ein verlässlicher Überblick: Was wurde geliefert, wer prüft es, und wie geht die Information weiter?','An invoice offers more than a document image. Start with a reliable overview: what was delivered, who checks it, and where does the information go next?')}</p><ol><li>${tr('Eingang: Wo kommen die Rechnungen an, und wer übernimmt?','Receipt: where do invoices arrive, and who takes responsibility?')}</li><li>${tr('Prüfung: Technische Meldungen und inhaltliche Rückfragen getrennt bearbeiten.','Checks: handle technical messages and questions about the actual transaction separately.')}</li><li>${tr('Freigabe: Verantwortliche und Vertretung festlegen.','Approval: define responsibilities and cover.')}</li><li>${tr('Weitergabe: Welche Daten müssen bisher erneut eingegeben werden?','Handover: which data currently needs to be entered again?')}</li><li>${tr('Wirkung: Bearbeitungszeit und Rückfragen vor und nach der Änderung vergleichen.','Impact: compare processing time and queries before and after the change.')}</li></ol><p>${tr('Das geplante Tool wird beim Lesen, technischen Prüfen und Erstellen helfen. Im Memberbereich ohne robin.vision-Hinweis auf eigenen Ausgaben. Die Entwicklung des gesamten Ablaufs ist Teil einer gesondert vereinbarten Zusammenarbeit.','The planned tool will help read, technically validate and create invoices. Members will be able to produce their own output without robin.vision branding. Development of the full workflow belongs to a separately agreed engagement.')}</p>`,questionnaire:`<p>${tr('Der Profilbogen ist die Grundlage für den von Robin vorbereiteten Memberbereich. Robin prüft die Angaben vor der Einladung.','The questionnaire is the starting point for the member area prepared by Robin. Robin reviews the answers before the invitation.')}</p><div class="action-row"><a class="button" href="/downloads/pilot-questionnaire-${state.lang}.pdf" download>${tr('PDF herunterladen','Download PDF')} ↓</a></div>`,onboarding:`<p>${tr('Ein Arbeitsimpuls für die Kanzlei: Einarbeitung beginnt mit klaren Zuständigkeiten und einem sicheren Weg für Rückfragen.','A working note for accounting firms: onboarding starts with clear responsibilities and a safe way to ask questions.')}</p><ol><li>${tr('Welche drei Dinge sollten in der ersten Woche klar sein?','Which three things should be clear in the first week?')}</li><li>${tr('Wer ist für welche Rückfrage ansprechbar?','Who can help with each kind of question?')}</li><li>${tr('Wann prüfen wir gemeinsam, was noch fehlt?','When will we check together what is still missing?')}</li></ol>`,handoff:`<p>${tr('Eine Übergabe ist mehr als eine Nachricht. Gemeinsam festhalten:','A handover is more than a message. Agree on:')}</p><ol><li>${tr('Welches Ergebnis wird weitergegeben?','What outcome is being handed over?')}</li><li>${tr('Welche Angaben müssen vollständig sein?','Which details must be complete?')}</li><li>${tr('Wer übernimmt den nächsten Schritt?','Who takes responsibility for the next step?')}</li><li>${tr('Wie wird eine offene Frage sichtbar?','How will open questions be made visible?')}</li></ol>`,vision:`<p>${tr('Eine digitale Idee verdient einen kleinen, überprüfbaren ersten Schritt.','A digital idea deserves a small, testable first step.')}</p><ol><li>${tr('Wessen Alltag soll leichter werden?','Whose working day should become easier?')}</li><li>${tr('Welche Annahme müssen wir zuerst prüfen?','Which assumption should we test first?')}</li><li>${tr('Wie lässt sich das ohne große Umsetzung ausprobieren?','How can we try it without a large implementation project?')}</li></ol>`};$('dialog-content').innerHTML=`<span class="small-label">${esc(item.type[state.lang==='de'?0:1])}</span><h2>${esc(item.title[state.lang==='de'?0:1])}</h2>${content[id]}${id!=='questionnaire'?`<p class="demo-caption">${tr('Fiktiver redaktioneller Beispielinhalt für den Prototyp.','Fictional editorial sample for this prototype.')}</p>`:''}`;$('resource-dialog').showModal();}
async function uploadPdf(e){e.preventDefault();if(state.busy)return;const file=$('pdf-file').files[0];if(!file){$('upload-status').textContent=tr('Bitte zunächst ein PDF auswählen.','Please choose a PDF first.');return;}if(file.size>2*1024*1024){$('upload-status').textContent=tr('Das PDF darf höchstens 2 MB groß sein.','The PDF must be no larger than 2 MB.');return;}state.busy=true;$('upload-form').querySelector('button').disabled=true;$('upload-status').textContent=tr('PDF wird lokal eingelesen …','Reading the PDF locally …');try{const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const data=await api('/import',{filename:file.name,pdfBase64:btoa(binary)});state.draft=data.draft;state.adminFields={...data.draft.fields};state.adminNotice=tr('PDF eingelesen. Vorschau prüfen; der Memberstand ist unverändert.','PDF imported. Review the preview; the member profile is unchanged.');state.invitation=false;}catch(error){state.adminNotice=error.message;}state.busy=false;render();}
async function publishProfile(e){e.preventDefault();if(state.busy)return;if(!$('review-confirm')?.checked||!state.draft)return;capture($('review-form'),state.adminFields);const payload={draftId:state.draft.id,fields:{...state.adminFields},confirmed:true,informalAddressApproved:$('informal-approved').checked,segments:[$('segment').value],reviewNote:$('review-note').value,nextFollowUp:{nextAt:$('followup-date').value,text:$('followup-note').value}};state.busy=true;$('publish-profile').disabled=true;try{await api('/publish',payload);await refresh();state.adminNotice=tr('Fassung lokal freigegeben. Jetzt lässt sich eine Demo-Einladung vorbereiten. Keine echte Robin-Prüfung wurde behauptet.','Version approved locally. A demo invitation can now be prepared. This does not claim a real review by Robin.');state.intakeFields={...fields()};toast(tr('Memberprofil erst nach ausdrücklicher Freigabe aktualisiert.','Member profile updated after explicit approval.'));}catch(error){state.busy=false;$('publish-status').textContent=error.message;$('publish-profile').disabled=false;return;}state.busy=false;render();}
$('admin-toggle').addEventListener('click',()=>go(state.view==='admin'?'collaboration':'admin'));$('close-dialog').addEventListener('click',()=>$('resource-dialog').close());$('resource-dialog').addEventListener('click',e=>{if(e.target===$('resource-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});document.querySelectorAll('[data-language]').forEach(b=>b.addEventListener('click',()=>{capture($('intake-form'),state.intakeFields);capture($('review-form'),state.adminFields);state.lang=b.dataset.language;state.notice='';if($('resource-dialog').open)$('resource-dialog').close();render();}));window.addEventListener('hashchange',()=>{render();$('main').focus();window.scrollTo({top:0,behavior:'smooth'});});render();(async()=>{const results=await Promise.allSettled([refresh(),api('/questionnaire')]);if(results[1].status==='fulfilled')state.schema=results[1].value;if(results[0].status==='fulfilled')state.intakeFields={...(state.draft?.fields||fields())};else{state.connected=false;state.adminNotice=tr('Der lokale Server ist nicht erreichbar. Bitte die Adresse des gestarteten lokalen Servers öffnen.','The local server is unavailable. Please use the address of the running local server.');}render();})();
